const tabId = 1962625075;
const nearbyAttractions = await browserjs(tabId, () => {
  // Find the element containing "Attractions near Hong Kong Disneyland"
  const allElements = Array.from(document.querySelectorAll('*'));
  const sectionTitleEl = allElements.find(el => el.textContent?.trim() === "Attractions near Hong Kong Disneyland");
  if (!sectionTitleEl) return "Section title not found";

  // Find the module container
  let container = sectionTitleEl.closest('[class*="NearbyModule"], [class*="nearby"], section, div');
  // let's look at the parent or surrounding elements
  let parent = sectionTitleEl.parentElement;
  while (parent && parent.querySelectorAll('[class*="Title_titleText"]').length === 0) {
    parent = parent.parentElement;
  }

  const cards = parent ? Array.from(parent.querySelectorAll('[class*="Title_titleBox"], [class*="card"]')) : [];
  return {
    sectionTitle: sectionTitleEl.textContent?.trim(),
    parentText: parent?.innerText,
    cardTexts: cards.map(c => c.innerText.replace(/\s+/g, ' '))
  };
});
console.log(JSON.stringify(nearbyAttractions, null, 2));

