const nearbyInfo = await browserjs(tabId, () => {
  const nearbyTab = document.querySelector('.search_nearby');
  // Look for any elements with id or class containing nearby or text containing Nearby Attractions
  const allElements = Array.from(document.querySelectorAll('*'));
  const matching = allElements.filter(el => {
    const t = el.textContent?.trim();
    return t && (t.includes('Nearby Attractions') || t.includes('Nearby') || t.includes('Attractions near'));
  }).map(el => ({
    tagName: el.tagName,
    className: el.className,
    text: el.textContent?.trim().slice(0, 150)
  }));
  return {
    nearbyTab: {
      tagName: nearbyTab?.tagName,
      className: nearbyTab?.className,
      text: nearbyTab?.textContent
    },
    matching: matching.slice(0, 20)
  };
});
